import sys, os, json, time, random, logging, tempfile

logging.basicConfig(level='INFO', stream=sys.stderr,
                    format='%(asctime)s %(levelname)s %(message)s')
log = logging.getLogger('export')

def write_atomic(path, obj):
    fd, tmp = tempfile.mkstemp(dir=os.path.dirname(path) or '.')
    try:
        with os.fdopen(fd, 'w') as f:
            json.dump(obj, f); f.flush(); os.fsync(f.fileno())
        os.replace(tmp, path)                 # atomic swap
    except BaseException:
        os.unlink(tmp); raise

def fetch_with_retry(attempts=5):
    for i in range(attempts):
        try:
            return fetch_export()
        except TransientError as e:           # only transient/idempotent
            if i == attempts - 1: raise
            delay = min(30.0, 2 ** i) + random.uniform(0, 1)
            log.warning('attempt %d failed (%s), retry in %.1fs', i+1, e, delay)
            time.sleep(delay)

def main():
    try:
        data = fetch_with_retry()
        write_atomic('/data/out.json', data)
        log.info('export ok')
        return 0
    except Exception:
        log.exception('export failed')        # ERROR + traceback to stderr
        return 1                              # cron/CI now see the failure

if __name__ == '__main__':
    sys.exit(main())                          # return value IS the exit code

Why: sys.exit(main()) makes the failure path return 1 so cron sees red; log.exception ships the message + traceback to stderr instead of an invisible print; fetch_with_retry rides out transient 503s with bounded exponential backoff + jitter and only retries the transient error; write_atomic writes a temp file and os.replace swaps it in, so a kill mid-write leaves the old or new whole file, never a truncated one.

